// Read-only: no tracking, no change detection
var recent = await db.Orders
    .AsNoTracking()
    .Where(o => o.CreatedAt >= cutoff)
    .OrderByDescending(o => o.CreatedAt)
    .Take(50)
    .ToListAsync();

// Project to a DTO: SELECT only the columns you need
var summary = await db.Orders
    .AsNoTracking()
    .Where(o => o.CustomerId == id)
    .Select(o => new OrderSummary(o.Id, o.Total, o.Status))
    .ToListAsync();

// Tracked update: the change tracker writes the UPDATE
var order = await db.Orders.SingleAsync(o => o.Id == id);
order.Status = OrderStatus.Shipped;
await db.SaveChangesAsync();
